171	package hotel.reservations;
172	
173	import hotel.documents.ReservationReceipt;
174	import hotel.messages.EmailSender;
175	import hotel.rooms.Room;
176	import hotel.rooms.Rooms;
177	import java.math.BigDecimal;
178	
179	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
180	public final class ReservationService {
181	
182	    static final String HOTEL_NAME = "Pousada Maré Alta";
183	
184	    private final Rooms rooms;
185	    private final ReservationStore store;
186	    private final PriceCalculator priceCalculator;
187	    private final EmailSender emailSender;
188	
189	    public ReservationService(
190	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
191	        this.rooms = rooms;
192	        this.store = store;
193	        this.priceCalculator = priceCalculator;
194	        this.emailSender = emailSender;
195	    }
196	
197	    public synchronized Reservation create(NewReservation request) {
198	        if (!request.checkOut().isAfter(request.checkIn())) {
199	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
200	        }
201	        if (request.guests() < 1) {
202	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
203	        }
204	        Room room = rooms.find(request.roomNumber())
205	                .orElseThrow(() -> new HotelException(
206	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
207	        if (request.guests() > room.capacity()) {
208	            throw new HotelException(
209	                    ErrorCode.CAPACITY_EXCEEDED,
210	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
211	        }
212	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
213	            throw new HotelException(
214	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
215	        }
216	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
217	        return store.add(request, price);
218	    }
219	
220	    public Reservation find(long reservationId) {
221	        return store.find(reservationId)
222	                .orElseThrow(() -> new HotelException(
223	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
224	    }
225	
226	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
227	    public synchronized Reservation confirm(long reservationId) {
228	        Reservation reservation = find(reservationId);
229	        if (reservation.status() != ReservationStatus.PENDING) {
230	            throw notAllowed(reservation, "confirm");
231	        }
232	        reservation.confirmPayment();
233	        store.update(reservation);
234	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
235	        emailSender.send(
236	                reservation.guest().email(),
237	                "Reserva confirmada - " + HOTEL_NAME,
238	                confirmationEmailBody(reservation, receipt));
239	        return reservation;
240	    }
241	
242	    /**
243	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
244	     * reservation was never paid, so nothing comes back).
245	     */
246	    public synchronized Reservation cancel(long reservationId) {
247	        Reservation reservation = find(reservationId);
248	        if (reservation.status() != ReservationStatus.PENDING
249	                && reservation.status() != ReservationStatus.CONFIRMED) {
250	            throw notAllowed(reservation, "cancel");
251	        }
252	        BigDecimal refund = switch (reservation.ratePlan()) {
253	            case STANDARD -> reservation.amountPaid();
254	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
255	        };
256	        reservation.cancel(refund);
257	        store.update(reservation);
258	        return reservation;
259	    }
260	
261	    public synchronized Reservation checkIn(long reservationId) {
262	        Reservation reservation = find(reservationId);
263	        if (reservation.status() != ReservationStatus.CONFIRMED) {
264	            throw notAllowed(reservation, "check in");
265	        }
266	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
267	        store.update(reservation);
268	        return reservation;
269	    }
270	
271	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
272	    public synchronized ReservationReceipt checkOut(long reservationId) {
273	        Reservation reservation = find(reservationId);
274	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
275	            throw notAllowed(reservation, "check out");
276	        }
277	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
278	        store.update(reservation);
279	        return new ReservationReceipt(reservation, roomOf(reservation));
280	    }
281	
282	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
283	    public ReservationReceipt receiptCopy(long reservationId) {
284	        Reservation reservation = find(reservationId);
285	        if (!reservation.isPaid()) {
286	            throw notAllowed(reservation, "issue a receipt for");
287	        }
288	        return new ReservationReceipt(reservation, roomOf(reservation));
289	    }
290	
291	    private Room roomOf(Reservation reservation) {
292	        return rooms.find(reservation.roomNumber()).orElseThrow();
293	    }
294	
295	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
296	        return "Olá, " + reservation.guest().name() + "!\n\n"
297	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
298	                + receipt.text() + "\n"
299	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
300	                + "Até breve!\n";
301	    }
302	
303	    private static HotelException notAllowed(Reservation reservation, String operation) {
304	        return new HotelException(
305	                ErrorCode.OPERATION_NOT_ALLOWED,
306	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
307	    }
308	}
309	package hotel.reports;
310	
311	import hotel.reservations.Reservation;
312	import hotel.reservations.ReservationStore;
313	import java.math.BigDecimal;
314	import java.time.YearMonth;
315	import java.util.ArrayList;
316	import java.util.Comparator;
317	import java.util.List;
318	
319	/**
320	 * The money the inn kept from the reservations that start in a given month, for the accountant (CSV).
321	 * A cancelled non-refundable reservation counts: the guest paid and nothing went back.
322	 */
323	public final class RevenueReport {
324	
325	    private final ReservationStore store;
326	
327	    public RevenueReport(ReservationStore store) {
328	        this.store = store;
329	    }
330	
331	    public String generate(YearMonth month) {
332	        List<Reservation> withRevenue = new ArrayList<>();
333	        for (Reservation reservation : store.all()) {
334	            boolean keptMoney = reservation.amountKept().signum() > 0;
335	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
336	            if (keptMoney && startsInMonth) {
337	                withRevenue.add(reservation);
338	            }
339	        }
340	        withRevenue.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
341	
342	        StringBuilder csv = new StringBuilder();
343	        csv.append("reservation,room,check_in,check_out,status,amount\n");
344	        BigDecimal revenue = BigDecimal.ZERO.setScale(2);
345	        for (Reservation reservation : withRevenue) {
346	            csv.append(reservation.id()).append(',')
347	                    .append(reservation.roomNumber()).append(',')
348	                    .append(reservation.checkIn()).append(',')
349	                    .append(reservation.checkOut()).append(',')
350	                    .append(reservation.status()).append(',')
351	                    .append(reservation.amountKept().toPlainString()).append('\n');
352	            revenue = revenue.add(reservation.amountKept());
353	        }
354	        csv.append("total,").append(revenue.toPlainString()).append('\n');
355	        return csv.toString();
356	    }
357	}

